def supported(count):return count in PATTERNS

def pairings(clubs,requested,legs=2):
 n=len(clubs)
 if not supported(n):raise ValueError('Unsupported mirrored league size')
 half=n if n%2 else n-1
 if requested<0 or requested>=half*legs:return []
 leg,rotation=divmod(requested,half)
 ids=([-1]+list(range(n))) if n%2 else list(range(n))
 rest=ids[1:];rest=rest[-rotation:]+rest[:-rotation] if rotation else rest
 order=[ids[0]]+rest;bits=PATTERNS[n][rotation];result=[];slot=0
 for i in range(len(ids)//2):
  a,b=order[i],order[-1-i]
  if a<0 or b<0:continue
  if bits[slot]=='0':a,b=b,a
  if leg%2:a,b=b,a
  result.append((clubs[a],clubs[b]));slot+=1
 return result

def upgrade_if_compatible(league):
 if league.schedule_version>=3 or not supported(len(league.clubs)):return False
 if league.format_key and league.round_index:
  from domestic_formats import specification
  if len(specification(league)['phases'])>1:return False
 def key(pairs):return [(h.uid or h.name,a.uid or a.name) for h,a in pairs]
 before=[key(league.pairings(r)) for r in range(league.round_index)]
 old=league.schedule_version;league.schedule_version=3
 if any(key(league.pairings(r))!=pairs for r,pairs in enumerate(before)):
  league.schedule_version=old;return False
 return True

